HYD_st.name='HYD'; 
HYD_st.lat=17.47;
HYD_st.lon=78.58;
HYD_st.alt=545;
HYD_st.env='con';
HYD_st.footp='U';
%%

%%
% data imported via the import tool from matlab

HYD_rd_h.Properties.DimensionNames{1}='Time';
HYD_rd_h.Properties.VariableNames{9}='Ba7_A';
HYD_rd_h.Properties.VariableNames{8}='Ba6_A';
HYD_rd_h.Properties.VariableNames{7}='Ba5_A';
HYD_rd_h.Properties.VariableNames{6}='Ba4_A';

HYD_rd_h.Properties.VariableNames{5}='Ba3_A';
HYD_rd_h.Properties.VariableNames{4}='Ba2_A';
HYD_rd_h.Properties.VariableNames{3}='Ba1_A';

names_rd=fieldnames(HYD_rd_h);
%%
% % % make abs
% % sigma=[18.47 14.54 13.14 11.58 10.35 7.77 7.19]; %for the 7 wavelengths with an exponent of -1
% % HYD_rd_h.Ba1_A=HYD_rd_h.Ba1_A .*sigma(1);
% % HYD_rd_h.Ba2_A=HYD_rd_h.Ba2_A .*sigma(2);
% % HYD_rd_h.Ba3_A=HYD_rd_h.Ba3_A .*sigma(3);
% % HYD_rd_h.Ba4_A=HYD_rd_h.Ba4_A .*sigma(4);
% % HYD_rd_h.Ba5_A=HYD_rd_h.Ba5_A .*sigma(5);
% % HYD_rd_h.Ba6_A=HYD_rd_h.Ba6_A .*sigma(6);
% % HYD_rd_h.Ba7_A=HYD_rd_h.Ba7_A .*sigma(7);


%%
HYD_rd=retime(HYD_rd_h,'daily',@nanmedian);
names_rd=fieldnames(HYD_rd);
%%
datevec(HYD_rd.Time(1)) % begin in 2016,  %[output:64594d52]
datevec(HYD_rd.Time(end)) % end in 2025 (with some months of 2026) %[output:1a187574]
plotFigControl(HYD_rd,HYD_st.name);  %[output:5410f5e0] %[output:295ac24c] %[output:2aac389b] %[output:7ab0b935] %[output:22ba0219] %[output:575558db] %[output:990dadab] %[output:3ecf0f31]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
HYD_cal=compute_exp_D(HYD_rd,names_abs,lambdaAE7); %[output:3553a35b] %[output:2f1e1b0f] %[output:65f452fd] %[output:9fdec103] %[output:51641f09] %[output:42257638] %[output:287baab7] %[output:9e5648cf] %[output:491765f1] %[output:7aa60ced] %[output:811aa9ee] %[output:3921ff4e] %[output:2132a82d] %[output:4e2b97fd]
plotFigControl_cal(HYD_cal,HYD_st.name); %[output:3803cf88] %[output:0acd60cb] %[output:420c08bc]
%%
%HOMOGENEITY

break_HYD_abs_BP=change_point_analysis_Def(HYD_rd,names_abs,0.05,'HYD','Absorption'); %[output:142d53ad] %[output:566e2925] %[output:985241e0] %[output:538557d7] %[output:95f9c400] %[output:7cb7de8f]
T_HYD_abs_BP=make_table_breakpoints_def(break_HYD_abs_BP); %[output:99c5ae24] %[output:411f7404] %[output:008dcfe7] %[output:0b398cc6] %[output:7fb8dc58] %[output:8bc0ffce] %[output:7f05115c]

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:247bff41]
break_HYD_expA_BP=change_point_analysis_Def(HYD_cal,names_expA,0.05,'HYD','Absorption exponent'); %[output:0601c916] %[output:33ea1d46] %[output:677222c6] %[output:27ffc039]
T_HYD_expA_BP=make_table_breakpoints_def(break_HYD_expA_BP); %[output:6f5a869e] %[output:58b26da8]
%%
HYD_tr=outerjoin(HYD_rd, HYD_cal);
HYD_tr.y=year(HYD_tr.Time);
% begin at the beginning of a year: 2016 
%end: 2025
P=timerange('2009-01-01','2019-01-01');
HYD_tr=HYD_tr(P,:);

% % names=fieldnames(HYD_tr);
% % c=startsWith(names,["U"]) | endsWith(names,["_dry","_A","_br","_gr"]) | contains(names,["00","3","tsi"]);
% % N=names(c);
% % for i=1:length(N)
% %     HYD_tr.(N{i})=[];
% % end
HYD_tr.DeltaT_Sec_=[];
HYD_tr.Flow_cm3_s_=[];
%
HYD_tr.Ba1_A=[];
HYD_tr.Ba2_A=[];
HYD_tr.Ba4_A=[];
HYD_tr.Ba5_A=[];
HYD_tr.Ba6_A=[];
HYD_tr.Ba7_A=[];


HYD_tr.expA_bgAE=[];
HYD_tr.expA_brAE=[];
HYD_tr.expA_grAE=[];
%%
% % % data in Mm-1
% % HYD_tr.Ba3_A=HYD_tr.Ba3_A.*1e6;
%%
[HYD_result_MK,HYD_result_LMSlog,HYD_result_LMSlin]=all_trend_STN(HYD_tr,HYD_st); %[output:57a23896] %[output:55c485ab] %[output:10f8625d] %[output:6b638428] %[output:070c8c0d] %[output:6a23d59e] %[output:7fe92e24] %[output:6506620f]

writetable(HYD_result_MK,'HYD_res_MK.txt'); %, 'delimiter',',' )
writetable(HYD_result_LMSlog,'HYD_res_LMSlog.txt'); 
writetable(HYD_result_LMSlin,'HYD_res_LMSlin.txt'); 
plot_10y_in_two(HYD_result_MK, HYD_st,'y');
%%
 timetable_to_netcdf(HYD_tr,'HYD_tr_def.nc'); %[output:1aa3bc16]

